import{_ as o,o as e,c as d,ag as r}from"./chunks/framework.DyZQ0-wY.js";const c=JSON.parse('{"title":"Controls","description":"","frontmatter":{},"headers":[],"relativePath":"footnotes/controls.md","filePath":"footnotes/controls.md"}'),a={name:"footnotes/controls.md"};function n(s,t,i,k,b,l){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="controls" tabindex="-1">Controls <a class="header-anchor" href="#controls" aria-label="Permalink to &quot;Controls&quot;">​</a></h1><p>Everything you need while practicing is on screen. The keyboard shortcuts below make it quicker.</p><h2 id="on-screen" tabindex="-1">On screen <a class="header-anchor" href="#on-screen" aria-label="Permalink to &quot;On screen&quot;">​</a></h2><p><strong>Top bar</strong></p><ul><li><strong>Playback:</strong> the song&#39;s speed, as a percentage. Lower it to slow the song down.</li><li><strong>Clap and metronome:</strong> the clap plays a tick on every step, and the metronome ticks on every beat.</li><li><strong>Speedmod:</strong> how fast the arrows scroll. <strong>X</strong> scales the scroll speed with the song&#39;s tempo, and <strong>C</strong> keeps it constant.</li></ul><p><strong>Bottom bar</strong></p><ul><li><strong>Skip to start</strong> and <strong>Skip to end</strong>.</li><li><strong>Play</strong> and <strong>Pause</strong>.</li><li><strong>Time</strong> and <strong>Beat:</strong> click either one to type the position you want to jump to.</li><li><strong>Charts:</strong> opens the chart list, so you can switch to another difficulty.</li><li><strong>Exit practice:</strong> switches to the full SMEditor chart editor.</li></ul><p><strong>Note layout</strong></p><p>The strip on the right edge shows the whole chart. Click or drag on it to jump to that part of the song. You can also scroll the mouse wheel over the arrows to move through the chart while it&#39;s paused.</p><h2 id="keyboard" tabindex="-1">Keyboard <a class="header-anchor" href="#keyboard" aria-label="Permalink to &quot;Keyboard&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Keys</th></tr></thead><tbody><tr><td>Play or pause</td><td><kbd>Space</kbd></td></tr><tr><td>Slower or faster</td><td><kbd>Shift</kbd>+<kbd>←</kbd> / <kbd>Shift</kbd>+<kbd>→</kbd></td></tr><tr><td>Slower or faster scrolling</td><td><kbd>Shift</kbd>+<kbd>↓</kbd> / <kbd>Shift</kbd>+<kbd>↑</kbd></td></tr><tr><td>Back to the start, or the end</td><td><kbd>Home</kbd> / <kbd>End</kbd></td></tr><tr><td>Back or forward one measure</td><td><kbd>Page Up</kbd> / <kbd>Page Down</kbd></td></tr><tr><td>Step on an arrow</td><td><kbd>←</kbd> <kbd>↓</kbd> <kbd>↑</kbd> <kbd>→</kbd>, or <kbd>A</kbd> <kbd>S</kbd> <kbd>W</kbd> <kbd>D</kbd></td></tr><tr><td>Clap on every step</td><td><kbd>F7</kbd></td></tr><tr><td>Metronome</td><td><kbd>Alt</kbd>+<kbd>F7</kbd></td></tr><tr><td>Volume</td><td><kbd>Alt</kbd>+<kbd>↑</kbd> / <kbd>Alt</kbd>+<kbd>↓</kbd></td></tr><tr><td>Choose another chart</td><td><kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>O</kbd> (<kbd>⌘</kbd>+<kbd>Shift</kbd>+<kbd>O</kbd> on a Mac)</td></tr><tr><td>Play along with judgments</td><td><kbd>P</kbd></td></tr><tr><td>Leave or enter practice mode</td><td><kbd>Shift</kbd>+<kbd>H</kbd></td></tr></tbody></table><p>The playback rate goes back to 100% when you reload the page.</p><h2 id="dancing-on-a-pad" tabindex="-1">Dancing on a pad <a class="header-anchor" href="#dancing-on-a-pad" aria-label="Permalink to &quot;Dancing on a pad&quot;">​</a></h2><p>Plug in a dance pad that works like a keyboard, sending the arrow keys, and dance along. Each step lights up its target arrow, and it doesn&#39;t change the song&#39;s position or speed. You can also step with the arrow keys or <kbd>W</kbd> <kbd>A</kbd> <kbd>S</kbd> <kbd>D</kbd> on the keyboard.</p><p>If your pad sends other keys, set them in <strong>Preferences &gt; Gameplay keybinds...</strong> in the chart editor (press <strong>Exit practice</strong> to get there). Pads that show up as a game controller instead of a keyboard need a key mapping tool, such as JoyToKey or AntiMicroX, to send keys.</p><h2 id="playing-along" tabindex="-1">Playing along <a class="header-anchor" href="#playing-along" aria-label="Permalink to &quot;Playing along&quot;">​</a></h2><p>Press <kbd>P</kbd> to play the chart yourself, with timing judgments, while the bot keeps dancing. Hit the arrows with your dance pad or the keyboard, as above. Press <kbd>Esc</kbd> or <kbd>P</kbd> to stop.</p>',17)])])}const p=o(a,[["render",n]]);export{c as __pageData,p as default};
